<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuery } from '@tanstack/vue-query'
import AsyncState from '@/components/AsyncState.vue'
import JudgeStatusBadge from '@/components/JudgeStatusBadge.vue'
import { listMySubmissions } from '@/api/submission'
import { readableError } from '@/api/errors'
import { formatMemory, formatShanghai } from '@/utils/format'
import type { LanguageId, Submission } from '@/api/types'
import { useSession } from '@/composables/useSession'
const route = useRoute(); const router = useRouter(); const session = useSession()
function text(v: unknown) { return typeof v === 'string' ? v : '' }
const filter = reactive({ problemNo: text(route.query.problemNo), language: text(route.query.language) as LanguageId | '', status: text(route.query.status), page: Number(route.query.page) || 1 })
const input = computed(() => ({ current: filter.page, pageSize: 20, problemNo: /^\d+$/.test(filter.problemNo) ? Number(filter.problemNo) : undefined, language: filter.language || undefined, status: filter.status === '' ? undefined : Number(filter.status), sortField: 'createTime', sortOrder: 'descend' }))
const query = useQuery({ queryKey: computed(() => ['submissions', session.user.value?.id, input.value]), queryFn: ({ signal }) => listMySubmissions(input.value, signal), enabled: computed(() => Boolean(session.user.value?.id)) })
function sync(reset = false) { if (reset) filter.page = 1; router.replace({ query: { ...(filter.problemNo && { problemNo: filter.problemNo }), ...(filter.language && { language: filter.language }), ...(filter.status !== '' && { status: filter.status }), page: String(filter.page) } }) }
watch(() => [filter.problemNo, filter.language, filter.status], () => sync(true))
</script>
<template><div class="page"><div class="page-head"><div><h1 class="page-title">我的提交</h1><p class="page-lead">查看每次提交的判题结果与运行信息</p></div></div><div class="filters surface"><el-input v-model="filter.problemNo" clearable placeholder="题目编号"/><el-select v-model="filter.language" clearable placeholder="全部语言"><el-option label="Java" value="java"/><el-option label="Python 3.12" value="python"/><el-option label="C++17" value="cpp"/></el-select><el-select v-model="filter.status" clearable placeholder="全部状态"><el-option label="等待判题" value="0"/><el-option label="判题中" value="1"/><el-option label="通过" value="2"/><el-option label="未通过" value="3"/></el-select></div><section class="surface table"><AsyncState :loading="query.isPending.value" :error="query.isError.value ? readableError(query.error.value) : undefined" :empty="query.data.value?.records.length === 0" empty-text="还没有提交记录" @retry="query.refetch()"><el-table :data="query.data.value?.records" stripe @row-click="(row:Submission) => $router.push(`/submissions/${row.id}`)"><el-table-column label="提交 ID" width="190"><template #default="{ row }"><span class="mono small">{{ row.id }}</span></template></el-table-column><el-table-column label="题目" min-width="210"><template #default="{ row }"><RouterLink :to="`/problems/${row.problemNo ?? row.questionId}`">#{{ row.problemNo ?? '—' }} {{ row.questionTitle || '' }}</RouterLink></template></el-table-column><el-table-column label="语言" prop="language" width="100"/><el-table-column label="结果" width="130"><template #default="{ row }"><JudgeStatusBadge :status="row.status" :verdict="row.verdict || row.judgeInfo?.message"/></template></el-table-column><el-table-column label="耗时" width="90"><template #default="{ row }">{{ row.judgeInfo?.executedTime ?? '—' }} ms</template></el-table-column><el-table-column label="内存" width="100"><template #default="{ row }">{{ formatMemory(row.judgeInfo?.executedMemory) }}</template></el-table-column><el-table-column label="提交时间" min-width="210"><template #default="{ row }">{{ formatShanghai(row.createTime) }}</template></el-table-column></el-table></AsyncState></section><div v-if="query.data.value" class="pager"><el-pagination v-model:current-page="filter.page" :page-size="20" layout="total,prev,pager,next" :total="query.data.value.total" @current-change="sync()"/></div></div></template>
<style scoped>.filters{display:grid;grid-template-columns:1fr 180px 180px;gap:12px;padding:14px;margin-bottom:16px}.table{overflow:hidden}.small{font-size:12px}.pager{display:flex;justify-content:flex-end;margin-top:18px}:deep(.el-table__row){cursor:pointer}@media(max-width:767px){.filters{grid-template-columns:1fr}.table{overflow-x:auto}.table :deep(.el-table){min-width:900px}}</style>
